"""Same-origin identity review UI. Tokens remain in the page, never browser storage."""
PAGE = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AfyaEvidence | Individual review</title><link rel="stylesheet" href="/identity.css"><script src="/identity.js" defer></script></head><body>
<header><h1>AfyaEvidence / Individual review</h1><p>Synthetic evidence only · Verified reviewer identity · No clinical approval</p></header><main>
<section><h2>Authenticate and load</h2><p>This service requires a short-lived access token from your configured identity provider. A development review token will not work.</p>
<label for="token">Access token <input id="token" type="password" autocomplete="off" spellcheck="false"></label><label for="run">Run ID <input id="run" autocomplete="off"></label><button id="load">Load investigation</button><button id="clear">Clear token and evidence</button><p id="message" role="status" aria-live="polite"></p></section>
<div id="content" hidden><section><h2>Investigation overview</h2><p id="principal"></p><p id="status"></p><p id="summary"></p><p id="execution"></p><p id="source"></p><table><thead><tr><th>Period</th><th>Canonical positives</th><th>Raw positives</th><th>Canonical tested</th><th>Positivity (%)</th></tr></thead><tbody id="metrics"></tbody></table><h3>Limitations</h3><ul id="limits"></ul></section>
<section><h2>Review history</h2><div id="history"></div><h3>Record one disposition</h3><label for="decision">Decision <select id="decision"><option value="request_more_evidence">Request more evidence</option><option value="accept">Accept for review record</option><option value="reject">Reject</option></select></label><label for="reason">Reason, 10–2,000 characters <textarea id="reason"></textarea></label><button id="submit" disabled>Record disposition</button><p id="reviewMessage"></p></section>
<section><details><summary>Technical evidence and provenance</summary><pre id="raw"></pre></details></section></div>
<section id="admin" hidden><h2>Managed-worker recovery</h2><p>Recovery stops remaining tasks and records an operator decision. It never restarts an investigation.</p><button id="jobs">Inspect jobs</button><pre id="jobList"></pre><label for="job">Job ID <input id="job"></label><label for="jobRevision">Expected revision <input id="jobRevision" type="number" min="0"></label><label for="recoveryReason">Recovery reason <textarea id="recoveryReason"></textarea></label><button id="recover">Stop and reconcile this job</button></section>
</main></body></html>'''
CSS = '''*{box-sizing:border-box}body{font:16px system-ui,sans-serif;margin:0;color:#142e44;background:#f1f5fa}header{background:#122e46;color:white;padding:1.4rem max(1.4rem,calc((100vw - 1100px)/2))}h1{font-size:1.6rem}main{max-width:1100px;margin:auto;padding:1rem}section{background:white;border:1px solid #dae4ee;border-radius:10px;padding:1.3rem;margin-bottom:1rem}h2{font-size:1.2rem}label{display:block;margin:.8rem 0}input,select,textarea{font:inherit;width:100%;padding:.65rem;border:1px solid #aebed0;border-radius:5px}textarea{min-height:90px}button{padding:.7rem 1rem;background:#0864ad;color:white;border:0;border-radius:5px;margin:.4rem;cursor:pointer}button:disabled{opacity:.45;cursor:default}table{width:100%;border-collapse:collapse;font-size:.9rem}th,td{padding:.7rem;text-align:left;border-bottom:1px solid #dbe5ee}th{background:#f1f5fa}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto}#message,#reviewMessage{white-space:pre-wrap}#history p{border-left:3px solid #aebed0;padding:.7rem}section{overflow:auto}'''
JS = r'''"use strict";
const $=id=>document.getElementById(id);
let loaded=null, principal=null, epoch=0, controller=null, intent=null, busy=false;
const value=v=>v===undefined||v===null?"Unavailable":String(v);
function clearEvidence(){loaded=null;principal=null;intent=null;epoch++;controller?.abort();$("content").hidden=true;$("admin").hidden=true;$("raw").textContent="";$("jobList").textContent="";$("reason").value="";$("submit").disabled=true;}
async function api(path,method="GET",body=null,signal){
 const response=await fetch(path,{method,signal,cache:"no-store",headers:{Authorization:"Bearer "+$("token").value,"Content-Type":"application/json"},body:body?JSON.stringify(body):undefined});
 const result=await response.json();if(!response.ok){const err=Error(result.error||"request_failed");err.status=response.status;throw err;}return result;
}
function render(run,actor){loaded=run;principal=actor;$("content").hidden=false;$("admin").hidden=!actor.roles.includes("administrator");
 $("principal").textContent="Authenticated: "+actor.subject+" | Issuer: "+actor.issuer+" | Roles: "+actor.roles.join(", ");
 $("status").textContent="Disposition: "+(run.disposition||"Not yet reviewed")+" | Revision: "+run.revision;
 $("summary").textContent=run.candidate.summary;const x=run.execution||{};$("execution").textContent="Data: "+value(x.data_mode)+" | Provider: "+value(x.model_mode)+" | Model: "+value(x.model)+" | Memory: "+value(x.memory_mode)+" | Profile: "+value(x.execution_profile);
 $("source").textContent="Provenance: "+run.provenance_status+". Imported receipt metadata, not a new live verification.";
 $("metrics").replaceChildren();for(const period of ["comparison","target"]){const tr=document.createElement("tr");const metrics=run.evidence.metrics||[];const get=(view,name)=>{const matches=metrics.filter(m=>m.period===period&&m.view===view&&m.name===name&&m.cohort==="all_available");return matches.length===1&&matches[0].availability==="available"&&typeof matches[0].value==="number"&&Number.isFinite(matches[0].value)?matches[0].value:null;};
 for(const item of [period,get("canonical","positive_total"),get("raw_diagnostic","positive_total"),get("canonical","tested_total"),get("canonical","positivity_pct")]){const td=document.createElement("td");td.textContent=value(item);tr.append(td);}$("metrics").append(tr);}
 $("limits").replaceChildren();for(const text of run.candidate.limitations||[]){const li=document.createElement("li");li.textContent=text;$("limits").append(li);}
 $("history").replaceChildren();for(const event of run.history){const p=document.createElement("p");const who=event.identity.kind==="verified_oidc"?event.identity.subject+" ("+event.identity.issuer+")":"Legacy identity—not individually verified: "+event.reviewer;p.textContent=event.at+" | "+who+" | "+event.disposition+" | "+event.reason;$("history").append(p);}
 $("raw").textContent=JSON.stringify(run,null,2);const writable=run.disposition===null&&actor.roles.includes("reviewer");$("submit").disabled=!writable;$("decision").disabled=!writable;$("reason").disabled=!writable;$("reviewMessage").textContent=writable?"Review the evidence before recording a decision.":run.disposition?"This run already has a recorded disposition. Nothing to fill here.":"Your role may view this run but cannot submit a review.";
}
async function load(){clearEvidence();const myEpoch=epoch;controller=new AbortController();const id=$("run").value.trim();try{const actor=await api("/api/me","GET",null,controller.signal);const run=await api("/api/runs/"+encodeURIComponent(id),"GET",null,controller.signal);if(epoch!==myEpoch)return;render(run,actor);$("message").textContent="Investigation loaded.";}catch(e){if(epoch===myEpoch){clearEvidence();$("message").textContent="Unable to load: "+e.message;}}}
$("load").addEventListener("click",load);for(const id of ["run","token"]){$(id).addEventListener("input",()=>{clearEvidence();$("message").textContent="Inputs changed. Load the investigation again.";});}
$("clear").addEventListener("click",()=>{clearEvidence();$("token").value="";$("message").textContent="Token and evidence cleared.";});
$("submit").addEventListener("click",async()=>{if(!loaded||busy)return;const run=loaded;const myEpoch=epoch;const body={expected_revision:run.revision,event_key:intent?.event_key||crypto.randomUUID().replaceAll("-",""),disposition:$("decision").value,reason:$("reason").value};if((Array.from(body.reason.trim()).length<10||Array.from(body.reason.trim()).length>2000)){$("reviewMessage").textContent="Provide 10–2,000 characters.";return;}
 if(intent&&(intent.reason!==body.reason||intent.disposition!==body.disposition)){ $("reviewMessage").textContent="An earlier response was uncertain. Reload before changing the decision.";return;}intent=body;busy=true;$("submit").disabled=true;
 try{const result=await api("/api/runs/"+encodeURIComponent(run.run_id)+"/reviews","POST",body);if(epoch===myEpoch){await load();$("message").textContent="Recorded "+result.disposition+" at revision "+result.revision+".";}}
 catch(e){if(epoch===myEpoch){$("reviewMessage").textContent="Submission not confirmed: "+e.message+". Retry unchanged or reload to inspect history.";$("submit").disabled=false;}}finally{busy=false;}});
$("jobs").addEventListener("click",async()=>{try{$("jobList").textContent=JSON.stringify(await api("/api/managed/jobs"),null,2);}catch(e){$("jobList").textContent=e.message;}});
$("recover").addEventListener("click",async()=>{const reason=$("recoveryReason").value;if((Array.from(reason.trim()).length<10||Array.from(reason.trim()).length>2000))return;const body={expected_revision:Number($("jobRevision").value),event_key:crypto.randomUUID().replaceAll("-",""),reason};$("recover").disabled=true;try{$("jobList").textContent=JSON.stringify(await api("/api/managed/jobs/"+encodeURIComponent($("job").value.trim())+"/reconcile","POST",body),null,2);}catch(e){$("jobList").textContent="Recovery not confirmed: "+e.message+". Inspect the audit before retrying.";}finally{$("recover").disabled=false;}});
'''
